package com.aigstudio.core

import kotlin.math.*

/** Analytic CAD intersections/convex offset + bounded triangulated shell QA.
 * Coordinates are millimeters. The wireframe view is never geometry truth.
 * No NC/G-code is generated by this module until caller validates its output.
 */
object AigAnalyticCadKernel {
    const val RESOLUTION_MM=0.001
    private const val TOL=1e-9
    data class ArcSpec(val center:Vec2,val radius:Double,val startRad:Double,val sweepRad:Double)
    data class MeshVerdict(val faces:Int,val edges:Int,val signedVolumeMm3:Double,val closedOriented:Boolean)
    private fun finite(p:Vec2)=p.x.isFinite()&&p.y.isFinite()&&abs(p.x)<1e6&&abs(p.y)<1e6
    private fun plus(a:Vec2,b:Vec2)=Vec2(a.x+b.x,a.y+b.y)
    private fun sub(a:Vec2,b:Vec2)=Vec2(a.x-b.x,a.y-b.y)
    private fun mul(a:Vec2,k:Double)=Vec2(a.x*k,a.y*k)
    private fun cross(a:Vec2,b:Vec2)=a.x*b.y-a.y*b.x
    private fun dot(a:Vec2,b:Vec2)=a.x*b.x+a.y*b.y
    private fun distance(a:Vec2,b:Vec2)=hypot(a.x-b.x,a.y-b.y)
    private fun valid(a:Vec2,b:Vec2){
        require(finite(a)&&finite(b)&&distance(a,b)>TOL){"CAD_DEGENERATE_OR_NONFINITE_LINE"}
    }
    private fun dedupe(items:List<Vec2>):List<Vec2> {
        val out=mutableListOf<Vec2>()
        items.forEach{p->if(out.none{distance(it,p)<=TOL})out+=p}
        return out
    }
    fun segmentSegment(a:Vec2,b:Vec2,c:Vec2,d:Vec2):List<Vec2>{
        valid(a,b);valid(c,d)
        val r=sub(b,a);val s=sub(d,c);val diff=sub(c,a)
        val denominator=cross(r,s);val scale=hypot(r.x,r.y)*hypot(s.x,s.y)
        if(abs(denominator)<=TOL*scale){
            if(abs(cross(diff,r))<=TOL*hypot(r.x,r.y)){
                val overlap=listOf(a,b,c,d).filter{p->
                    fun on(x:Vec2,y:Vec2)=
                        abs(cross(sub(y,x),sub(p,x)))<=TOL*distance(x,y) &&
                        dot(sub(p,x),sub(p,y))<=TOL
                    on(a,b)&&on(c,d)
                }
                require(dedupe(overlap).size<=1){"CAD_COLLINEAR_OVERLAP_NEEDS_TOPOLOGY_REPAIR"}
                return dedupe(overlap)
            }
            return emptyList()
        }
        val t=cross(diff,s)/denominator;val u=cross(diff,r)/denominator
        if(t < -TOL||t > 1+TOL||u < -TOL||u > 1+TOL)return emptyList()
        return listOf(plus(a,mul(r,t.coerceIn(0.0,1.0))))
    }
    fun segmentCircle(a:Vec2,b:Vec2,center:Vec2,radius:Double):List<Vec2>{
        valid(a,b)
        require(finite(center)&&radius.isFinite()&&radius>TOL&&radius<1e6){
            "CAD_INVALID_CIRCLE"
        }
        val ray=sub(b,a);val delta=sub(a,center)
        val qa=dot(ray,ray);val qb=2*dot(delta,ray)
        val qc=dot(delta,delta)-radius*radius
        val discriminant=qb*qb-4*qa*qc
        val budget=TOL*max(1.0,abs(qb*qb)+abs(4*qa*qc))
        if(discriminant < -budget)return emptyList()
        val root=sqrt(max(0.0,discriminant))
        val t1=(-qb-root)/(2*qa);val t2=(-qb+root)/(2*qa)
        return dedupe(listOf(t1,t2).filter{it>=-TOL&&it<=1+TOL}
            .map{plus(a,mul(ray,it.coerceIn(0.0,1.0)))}).sortedBy{dot(sub(it,a),ray)}
    }
    fun circleCircle(c1:Vec2,r1:Double,c2:Vec2,r2:Double):List<Vec2>{
        require(finite(c1)&&finite(c2)&&
            r1.isFinite()&&r2.isFinite()&&r1>TOL&&r2>TOL){ "CAD_INVALID_CIRCLES" }
        val distance=distance(c1,c2)
        require(distance>TOL || abs(r1-r2)>TOL){"CAD_COINCIDENT_CIRCLES"}
        if(distance>TOL && (distance>r1+r2+TOL||distance<abs(r1-r2)-TOL))
            return emptyList()
        if(distance<=TOL)return emptyList()
        val x=(r1*r1-r2*r2+distance*distance)/(2*distance)
        val height2=r1*r1-x*x
        if(height2 < -TOL)return emptyList()
        val unit=mul(sub(c2,c1),1/distance)
        val base=plus(c1,mul(unit,x));val h=sqrt(max(0.0,height2))
        return dedupe(listOf(Vec2(base.x-unit.y*h,base.y+unit.x*h),
            Vec2(base.x+unit.y*h,base.y-unit.x*h))).sortedWith(
                compareBy<Vec2>{it.x}.thenBy{it.y})
    }
    fun segmentArc(a:Vec2,b:Vec2,arc:ArcSpec):List<Vec2>{
        require(listOf(arc.radius,arc.startRad,arc.sweepRad).all{it.isFinite()} &&
            arc.radius>TOL && abs(arc.sweepRad)>TOL &&
            abs(arc.sweepRad)<=2*PI+TOL){"CAD_INVALID_ARC"}
        fun forward(x:Double)=((x%(2*PI))+(2*PI))%(2*PI)
        return segmentCircle(a,b,arc.center,arc.radius).filter { p ->
            val angle=atan2(p.y-arc.center.y,p.x-arc.center.x)
            if(abs(arc.sweepRad)>=2*PI-TOL)true
            else if(arc.sweepRad>0)forward(angle-arc.startRad)<=arc.sweepRad+TOL
            else forward(arc.startRad-angle)<=-arc.sweepRad+TOL
        }
    }
    /** Signed distance: + expands the contour, - shrinks it.
     * STRICTLY convex closed rings only; concave/offset self-intersection BLOCKED.
     */
    fun offsetClosedConvex(input:List<Vec2>,distanceMm:Double):List<Vec2>{
        require(distanceMm.isFinite()&&abs(distanceMm)<=10000.0){
            "CAD_OFFSET_INVALID_DISTANCE"}
        val ring=CadClosedContourTopology.inspect(input)
            ?:error("CAD_OFFSET_INVALID_TOPOLOGY")
        val p=ring.points
        require(p.size<=256){"CAD_OFFSET_VERTEX_LIMIT"}
        var doubleArea=0.0
        for(i in p.indices)doubleArea+=cross(p[i],p[(i+1)%p.size])
        val orientation=if(doubleArea>0.0)1.0 else -1.0
        val normals=p.indices.map{i->
            val v=sub(p[(i+1)%p.size],p[i]);val len=hypot(v.x,v.y)
            Vec2(orientation*v.y/len,-orientation*v.x/len)
        }
        for(i in p.indices){
            val prev=sub(p[i],p[(i+p.size-1)%p.size])
            val next=sub(p[(i+1)%p.size],p[i])
            val turn=cross(prev,next)*orientation
            require(turn>1e-8*hypot(prev.x,prev.y)*hypot(next.x,next.y)){
                "CAD_OFFSET_NONCONVEX_OR_COLLINEAR"
            }
        }
        val result=p.indices.map {i->
            val j=(i+p.size-1)%p.size
            val a=plus(p[j],mul(normals[j],distanceMm))
            val b=plus(p[i],mul(normals[j],distanceMm))
            val c=plus(p[i],mul(normals[i],distanceMm))
            val e=plus(p[(i+1)%p.size],mul(normals[i],distanceMm))
            val r=sub(b,a);val s=sub(e,c)
            val denom=cross(r,s)
            require(abs(denom)>TOL*hypot(r.x,r.y)*hypot(s.x,s.y)){
                "CAD_OFFSET_PARALLEL_EDGES"
            }
            val t=cross(sub(c,a),s)/denom
            plus(a,mul(r,t))
        }
        require(result.all(::finite)){"CAD_OFFSET_NONFINITE"}
        // Inward offsets must stay inside ALL shifted support half-planes,
        // otherwise the tool radius exceeds the feature's actual clearance.
        for(vertex in result)for(i in p.indices){
            require(dot(normals[i],sub(vertex,p[i]))<=distanceMm+1e-7){
                "CAD_OFFSET_COLLAPSED_OR_INVERTED"
            }
        }
        val closed=result+result.first()
        require(CadClosedContourTopology.inspect(closed)!=null){
            "CAD_OFFSET_SELF_INTERSECTION"
        }
        return closed
    }
}

/** Topology proof only: checks a triangle surface is closed, consistently
 * oriented, with positive/non-zero volume. Not a B-rep or boolean solid.
 */
object AigTriangleShellTopology {
    data class Verdict(val faceCount:Int,val uniqueEdges:Int,val absVolumeMm3:Double)
    fun requireClosed(
        vertices:List<Triple<Double,Double,Double>>,
        triangles:List<Triple<Int,Int,Int>>
    ):Verdict{
        require(vertices.size in 4..200000 && triangles.size in 4..400000){
            "CAD_SHELL_INVALID_BUDGET"
        }
        require(vertices.all{(x,y,z)->listOf(x,y,z).all{it.isFinite()&&abs(it)<1e6}}){
            "CAD_SHELL_NONFINITE"
        }
        val edges=HashMap<Pair<Int,Int>,MutableList<Int>>()
        var sixVolume=0.0
        fun vector(index:Int)=vertices[index]
        triangles.forEach{(a,b,c)->
            require(listOf(a,b,c).all{it in vertices.indices}&&
                a!=b&&b!=c&&a!=c){"CAD_SHELL_DEGENERATE_INDEX"}
            val p=vector(a);val q=vector(b);val r=vector(c)
            val ux=q.first-p.first;val uy=q.second-p.second;val uz=q.third-p.third
            val vx=r.first-p.first;val vy=r.second-p.second;val vz=r.third-p.third
            val nx=uy*vz-uz*vy;val ny=uz*vx-ux*vz;val nz=ux*vy-uy*vx
            require(hypot(hypot(nx,ny),nz)>1e-12){"CAD_SHELL_ZERO_AREA_FACE"}
            sixVolume+=p.first*(q.second*r.third-q.third*r.second)+
                p.second*(q.third*r.first-q.first*r.third)+
                p.third*(q.first*r.second-q.second*r.first)
            for((x,y) in listOf(a to b,b to c,c to a)){
                val key=min(x,y) to max(x,y)
                edges.getOrPut(key){mutableListOf()}.add(if(x<y)1 else -1)
            }
        }
        require(edges.values.all{it.size==2&&it.sum()==0}){
            "CAD_SHELL_OPEN_NONMANIFOLD_OR_INCONSISTENT_WINDING"
        }
        val volume=abs(sixVolume)/6.0
        require(volume.isFinite()&&volume>1e-9){"CAD_SHELL_ZERO_VOLUME"}
        return Verdict(triangles.size,edges.size,volume)
    }
}
